import{_ as t,o as e,c as s,a2 as a}from"./chunks/framework.BBd5PKnH.js";const d=JSON.parse('{"title":"JWT, OAuth2, IdP, Access Token — Phân biệt các khái niệm trong Authentication & Authorization","description":"Mỗi lần làm tính năng login là lại gặp một đống thuật ngữ: OAuth2, JWT, IdP, access token, refresh token, SSO... ","frontmatter":{"title":"JWT, OAuth2, IdP, Access Token — Phân biệt các khái niệm trong Authentication & Authorization","description":"Mỗi lần làm tính năng login là lại gặp một đống thuật ngữ: OAuth2, JWT, IdP, access token, refresh token, SSO... ","date":"2026-05-31T00:00:00.000Z"},"headers":[],"relativePath":"notes/jwt-oauth2-idp-access-token-phan-biet-cac-khai-niem-trong-authentication-authorization.md","filePath":"notes/jwt-oauth2-idp-access-token-phan-biet-cac-khai-niem-trong-authentication-authorization.md"}'),i={name:"notes/jwt-oauth2-idp-access-token-phan-biet-cac-khai-niem-trong-authentication-authorization.md"};function o(h,n,p,r,l,c){return e(),s("div",null,[...n[0]||(n[0]=[a(`<p>Mỗi lần làm tính năng login là lại gặp một đống thuật ngữ: OAuth2, JWT, IdP, access token, refresh token, SSO... Bài này mình sẽ phân biệt từng khái niệm, vẽ ra luồng thực tế, và chỉ rõ chúng liên quan với nhau như thế nào.</p><h2 id="idp-—-identity-provider" tabindex="-1">IdP — Identity Provider <a class="header-anchor" href="#idp-—-identity-provider" aria-label="Permalink to &quot;IdP — Identity Provider&quot;">​</a></h2><p><strong>IdP</strong> là hệ thống xác minh danh tính người dùng và phát token. Google, GitHub, Facebook, Okta, Auth0, Keycloak, Authentik... đều là IdP.</p><blockquote><p>⚠️ Ảnh thiếu: <strong>Screenshot 2026-05-31 at 23.14.15.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p><strong>① Click &quot;Login with Google&quot;</strong> Bạn bấm nút. App nói: &quot;tao không tự xác minh mày, tao gửi mày sang Google.&quot;</p><p><strong>② App redirect về Google</strong> App tạo một URL dạng <code>google.com/auth?client_id=...&amp;scope=openid</code> rồi bảo trình duyệt gửi request đến đó. App xong việc, ngồi chờ response từ Google.</p><p><strong>③ Trình duyệt đến Google</strong> Trình duyệt thực sự chạy sang Google — giống như bạn gõ địa chỉ mới vào thanh URL.</p><p><strong>④ Google hiện form đăng nhập</strong> Form này là của Google, App không quản lý.</p><p><strong>⑤ Bạn nhập email + password</strong> Password đi thẳng vào server Google. App không handle/ ko lưu password của user — đây là điểm mấu chốt của toàn bộ hệ thống.</p><p><strong>⑥ Google trả về Authorization Code</strong> Google xác minh xong, nhưng <strong>không trả token ngay</strong>. Thay vào đó Google redirect trình duyệt về App kèm một cái code ngắn, kiểu: <code>yourapp.com/callback?code=4/0AX4...</code>. Code này sống khoảng 10 giây, dùng 1 lần.</p><p><strong>⑦ Trình duyệt forward code về App</strong></p><p><strong>⑧ App gọi thẳng Google để đổi code</strong> Đây là bước quan trọng nhất. App gọi API Google từ <strong>server của mình</strong> — không qua trình duyệt — kèm theo <code>code</code> vừa nhận và <code>client_secret</code> của backend.</p><p><strong>⑨ Google trả token thật</strong> Google xác nhận code hợp lệ + secret đúng → trả về <code>access_token</code> (để gọi API), <code>id_token</code> (JWT chứa tên, email, user ID của bạn), <code>refresh_token</code>. Token đi qua kênh server-to-server, không qua trình duyệt.</p><p><strong>⑩ App tạo session, đăng nhập xong</strong> App dựa <code>id_token</code> ra biết bạn là ai, tạo session, trả cookie về trình duyệt. Từ giờ bạn đã logged in. App có thể định danh được user mà ko cần lưu credentials</p><h2 id="oauth2-—-giao-thuc-uy-quyen" tabindex="-1">OAuth2 — Giao thức ủy quyền <a class="header-anchor" href="#oauth2-—-giao-thuc-uy-quyen" aria-label="Permalink to &quot;OAuth2 — Giao thức ủy quyền&quot;">​</a></h2><p><strong>OAuth2</strong> là một <em>giao thức</em> định nghĩa cách một ứng dụng xin quyền truy cập tài nguyên thay mặt người dùng. Giao diện thường thấy của Google OAuth2:</p><blockquote><p>⚠️ Ảnh thiếu: <strong>authz-single-consent.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>Ví dụ thực tế: App muốn truy cập Google Calendar của bạn, nó sẽ redirect sang UI của Google, Google confirm viuws user như ảnh: &quot;App X muốn đọc calendar của bạn, đồng ý không?&quot; Nếu user đồng ý, Google cấp token cho app và app dùng token đó để gọi Google Calendar API</p><p><strong>Quan trọng:</strong> OAuth2 ban đầu là về <em>authorization</em> (ủy quyền truy cập resource), không phải authentication. Nhưng nó thường bị dùng cho cả login — đó là lý do OpenID Connect ra đời.</p><h2 id="openid-connect-oidc" tabindex="-1">OpenID Connect (OIDC) <a class="header-anchor" href="#openid-connect-oidc" aria-label="Permalink to &quot;OpenID Connect (OIDC)&quot;">​</a></h2><p><strong>OIDC</strong> là một lớp identity xây trên OAuth2. Nếu OAuth2 sẽ quản lý authorization, thì OIDC sẽ quản phẩn authentication</p><p>OIDC thêm vào OAuth2:</p><ul><li><strong>ID Token</strong> — chứa thông tin về user (name, email, sub)</li><li><strong>UserInfo endpoint</strong> — lấy thêm thông tin user</li><li><strong>Standardized scopes</strong> — <code>openid</code>, <code>profile</code>, <code>email</code></li></ul><p>Khi bạn dùng &quot;Login with Google&quot;, thực ra bạn đang dùng OAuth2 + OIDC.</p><h2 id="jwt-—-json-web-token" tabindex="-1">JWT — JSON Web Token <a class="header-anchor" href="#jwt-—-json-web-token" aria-label="Permalink to &quot;JWT — JSON Web Token&quot;">​</a></h2><p><strong>JWT</strong> là <em>format</em> của token — không phải giao thức, không phải hệ thống.</p><p>Cấu trúc JWT gồm 3 phần, ngăn cách bằng dấu <code>.</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>eyJhbGciOiJSUzI1NiJ9.eyJzdWIiOiJ1c2VyMTIzIiwibmFtZSI6IlR1IE15IiwiZXhwIjoxNzE2MDAwMDAwfQ.signature</span></span>
<span class="line"><span>      Header                              Payload                                    Signature</span></span></code></pre></div><p><strong>Header</strong> — thuật toán ký (RS256, HS256...)<br><strong>Payload</strong> — claims: thông tin user, thời gian hết hạn, issuer...<br><strong>Signature</strong> — chữ ký để verify tính toàn vẹn</p><p>Decode payload ra:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;67......2b1b412285&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ple.tumy@gmail.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;jti&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1bac......15f0eecd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;exp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1780271782</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;iat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1780242982</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="access-token" tabindex="-1">Access Token <a class="header-anchor" href="#access-token" aria-label="Permalink to &quot;Access Token&quot;">​</a></h2><p><strong>Access Token</strong> là token dùng để truy cập API/resource trên server.</p><p>Đặc điểm:</p><ul><li><strong>Short-lived</strong> — thường 15 phút đến 1 giờ</li><li>Gửi kèm trong <code>Authorization: Bearer &lt;token&gt;</code> header</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → GET /api/posts</span></span>
<span class="line"><span>         Authorization: Bearer eyJhbGci...</span></span>
<span class="line"><span>         </span></span>
<span class="line"><span>Server → verify token → trả data</span></span></code></pre></div><h2 id="refresh-token" tabindex="-1">Refresh Token <a class="header-anchor" href="#refresh-token" aria-label="Permalink to &quot;Refresh Token&quot;">​</a></h2><p><strong>Refresh Token</strong> giải quyết vấn đề access token ngắn hạn.</p><p>Khi access token hết hạn, thay vì bắt user login lại:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Client → POST /auth/token</span></span>
<span class="line"><span>         grant_type=refresh_token</span></span>
<span class="line"><span>         refresh_token=&lt;refresh_token&gt;</span></span>
<span class="line"><span>         </span></span>
<span class="line"><span>Auth Server → access_token mới + refresh_token mới</span></span></code></pre></div><p>Đặc điểm:</p><ul><li><strong>Long-lived</strong> — thường 7-30 ngày</li><li>Được lưu an toàn (httpOnly cookie, secure storage)</li><li>Chỉ gửi đến auth server, không đến resource server</li><li>Có thể bị revoke — khi user logout, đổi password</li></ul><h2 id="sso-—-single-sign-on" tabindex="-1">SSO — Single Sign-On <a class="header-anchor" href="#sso-—-single-sign-on" aria-label="Permalink to &quot;SSO — Single Sign-On&quot;">​</a></h2><p><strong>SSO</strong> là trải nghiệm &quot;đăng nhập một lần, dùng nhiều app&quot;. Kỹ thuật bên dưới thường là OAuth2/OIDC với shared IdP.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User login vào Google một lần</span></span>
<span class="line"><span>→ Mở Gmail    → Google confirm session → vào thẳng</span></span>
<span class="line"><span>→ Mở Drive    → Google confirm session → vào thẳng</span></span>
<span class="line"><span>→ Mở YouTube  → Google confirm session → vào thẳng</span></span></code></pre></div><p>Trong enterprise: Okta/Azure AD là IdP trung tâm, tất cả app (Slack, GitHub, Jira...) đều delegate identity về đó.</p><h2 id="tom-tat-quan-he-giua-cac-khai-niem" tabindex="-1">Tóm tắt quan hệ giữa các khái niệm <a class="header-anchor" href="#tom-tat-quan-he-giua-cac-khai-niem" aria-label="Permalink to &quot;Tóm tắt quan hệ giữa các khái niệm&quot;">​</a></h2><blockquote><p>⚠️ Ảnh thiếu: <strong>Screenshot 2026-05-31 at 23.37.56.png</strong> (không có trong dữ liệu export, cần upload lại thủ công)</p></blockquote><p>OAuth2 → Giao thức ủy quyền └── OIDC → Thêm lớp identity lên OAuth2</p><p>IdP → Hệ thống thực thi OAuth2/OIDC (Google, Auth0...)</p><p>JWT → Format của token (dùng trong access token, id token)</p><p>Access Token → Token ngắn hạn để gọi API Refresh Token → Token dài hạn để lấy access token mới ID Token → JWT chứa thông tin user (từ OIDC)</p><p>SSO → Trải nghiệm người dùng, implement bằng OAuth2/OIDC</p>`,53)])])}const u=t(i,[["render",o]]);export{d as __pageData,u as default};
